import sys
from heapq import heappop, heappush
from collections import defaultdict, deque

def min_days_to_pass_exams(n, m, days, preparation_days):
    # Create a list of lists to store the days each subject can be passed
    subject_days = defaultdict(list)
    for day, subject in enumerate(days):
        if subject != 0:
            subject_days[subject].append(day)

    # Priority queue to keep track of the earliest day each subject can be passed
    pq = []
    # Dictionary to keep track of the last preparation day for each subject
    last_prep_day = {}
    # Total days passed
    total_days = 0

    for day in range(n):
        # Check if there's an exam today
        if days[day] != 0:
            subject = days[day]
            # If we have already prepared for this subject, we can pass it today
            if subject in last_prep_day and last_prep_day[subject] <= day:
                heappush(pq, (day + 1, subject))
            else:
                # If we haven't prepared, we need to prepare and then pass it
                prep_end_day = day + preparation_days[subject - 1]
                if prep_end_day <= n:
                    heappush(pq, (prep_end_day, subject))
                    last_prep_day[subject] = prep_end_day
                else:
                    return -1  # Not enough days to prepare for this exam

        # Pass the exam with the earliest possible day
        while pq and pq[0][0] <= day:
            _, subject = heappop(pq)
            total_days += 1

    # Check if all exams have been passed
    if total_days == m:
        return total_days
    else:
        return -1

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    days = list(map(int, data[2:n+2]))
    preparation_days = list(map(int, data[n+2:n+2+m]))

    result = min_days_to_pass_exams(n, m, days, preparation_days)
    print(result)

if __name__ == "__main__":
    main()
